<?php defined('BASEPATH') or exit('No direct script access allowed');init_head();?><div id="wrapper"><div class="content"><div class="tw-flex tw-justify-between tw-items-center tw-mb-3"><h4 class="tw-font-bold tw-text-xl"><?=_l('scr_sale_types')?></h4><button class="btn btn-primary" data-toggle="modal" data-target="#scrTypeModal" onclick="scrTypeNew()"><i class="fa fa-plus"></i> <?=_l('scr_add')?></button></div><div class="panel_s"><div class="panel-body"><table class="table dt-table"><thead><tr><th>#</th><th><?=_l('scr_sale_type_name')?></th><th><?=_l('scr_status')?></th><th><?=_l('scr_options')?></th></tr></thead><tbody><?php foreach($types as $r):?><tr><td><?=(int)$r['id']?></td><td><?=html_escape($r['name'])?></td><td><?=$r['active']?_l('scr_active'):_l('scr_inactive')?></td><td><button class="btn btn-default btn-icon scr-type-edit" data-toggle="modal" data-target="#scrTypeModal" data-id="<?=(int)$r['id']?>" data-name="<?=html_escape($r['name'])?>" data-active="<?=(int)$r['active']?>"><i class="fa fa-pencil"></i></button> <form method="post" action="<?=admin_url('sales_commercial_rules/delete_sale_type/'.(int)$r['id'])?>" style="display:inline"><?=form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash())?><button class="btn btn-danger btn-icon"><i class="fa fa-trash"></i></button></form></td></tr><?php endforeach?></tbody></table></div></div></div></div><div class="modal fade" id="scrTypeModal"><div class="modal-dialog"><div class="modal-content"><form method="post"><?=form_hidden($this->security->get_csrf_token_name(),$this->security->get_csrf_hash())?><input type="hidden" name="id" value="0"><div class="modal-header"><button class="close" type="button" data-dismiss="modal">&times;</button><h4 class="modal-title"><?=_l('scr_sale_types')?></h4></div><div class="modal-body"><?=render_input('name','scr_sale_type_name','','text',['required'=>true])?><?=render_select('active',[['id'=>1,'name'=>_l('scr_active')],['id'=>0,'name'=>_l('scr_inactive')]],['id','name'],'scr_status',1)?></div><div class="modal-footer"><button type="button" class="btn btn-default" data-dismiss="modal"><?=_l('scr_cancel_edit')?></button><button class="btn btn-primary"><?=_l('scr_saved')?></button></div></form></div></div></div><?php init_tail();?><script>init_selectpicker();function scrTypeNew(){var m=jQuery('#scrTypeModal');m.find('form')[0].reset();m.find('[name=id]').val(0);m.find('[name=active]').val(1).selectpicker('refresh')}jQuery('.scr-type-edit').click(function(){var b=jQuery(this),m=jQuery('#scrTypeModal');m.find('[name=id]').val(b.data('id'));m.find('[name=name]').val(b.data('name'));m.find('[name=active]').val(b.data('active')).selectpicker('refresh')});</script></body></html>
